from pathlib import Path
import base64,gzip,json,hashlib
BASE='f344cc277f575dafaa4bfdf9cfcd4b870b1eda72'
TARGET='4081ebeaf357755d5f4630f35883e2505a30a600'
PAYLOAD=''''''

def gitsha(b):
    return hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()

p=Path('index.html')
raw=p.read_bytes()
if gitsha(raw)!=BASE:
    raise SystemExit('base index SHA mismatch: '+gitsha(raw))
lines=raw.decode('utf-8').splitlines(keepends=True)
ops=json.loads(gzip.decompress(base64.b64decode(PAYLOAD)).decode('utf-8'))
for i1,i2,repl in reversed(ops):
    lines[i1:i2]=repl.splitlines(keepends=True)
out=''.join(lines).encode('utf-8')
if len(out)!=1431377:
    raise SystemExit('target size mismatch: '+str(len(out)))
if gitsha(out)!=TARGET:
    raise SystemExit('target SHA mismatch: '+gitsha(out))
p.write_bytes(out)
print('verified',TARGET,len(out))
